import * as THREE from '../classroom-chase/three.module.min.js';
import {obstacles} from './map.js';
const canvas=document.querySelector('#game'),stage=document.querySelector('#stage'),overlay=document.querySelector('#overlay'),title=document.querySelector('#title'),description=document.querySelector('#description'),roomForm=document.querySelector('#room-form'),lobby=document.querySelector('#lobby'),roomCode=document.querySelector('#code'),connection=document.querySelector('#connection'),roomLabel=document.querySelector('#room-label'),roomToggle=document.querySelector('#room-toggle'),shareCode=document.querySelector('#share-code'),playersLabel=document.querySelector('#players-label'),lobbyStatus=document.querySelector('#lobby-status'),startRound=document.querySelector('#start-round'),roleEl=document.querySelector('#role'),timeEl=document.querySelector('#time'),timeCaption=document.querySelector('#time-caption'),roleFlash=document.querySelector('#role-flash'),remainingEl=document.querySelector('#remaining'),hint=document.querySelector('#hint');
const scene=new THREE.Scene();scene.background=new THREE.Color('#c6eaf3');scene.fog=new THREE.Fog('#c6eaf3',55,130);const camera=new THREE.PerspectiveCamera(52,16/9,.1,220),renderer=new THREE.WebGLRenderer({canvas,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.outputColorSpace=THREE.SRGBColorSpace;scene.add(new THREE.HemisphereLight('#ffffff','#8bad86',2.2));const sun=new THREE.DirectionalLight('#fff4d9',2);sun.position.set(-25,45,25);scene.add(sun);
const material=color=>new THREE.MeshStandardMaterial({color,roughness:.9});const materials={grass:material('#a9d69d'),path:material('#d9cbb0'),trunk:material('#987653'),leaves:material('#73b883'),roof:material('#8a7896'),window:material('#9ed8ef'),door:material('#916c57'),skin:material('#ffddbd'),hair:material('#514d60'),pants:material('#59647d'),black:material('#303449'),red:material('#f57276')};
function box(w,h,d,m,x,y,z,parent=scene){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);parent.add(o);return o}function sphere(radius,m,x,y,z,parent){const o=new THREE.Mesh(new THREE.SphereGeometry(radius,12,10),m);o.position.set(x,y,z);parent.add(o);return o}
box(150,.3,150,materials.grass,0,-.15,0);for(const x of [-40,-13,14,41])box(5,.03,150,materials.path,x,.02,0);for(const z of [-40,-13,14,41])box(150,.03,5,materials.path,0,.025,z);
for(const o of obstacles){if(o.kind==='house'){const m=material(o.color);box(o.w,5.2,o.d,m,o.x,2.6,o.z);const roof=new THREE.Mesh(new THREE.ConeGeometry(7,2.7,4),materials.roof);roof.position.set(o.x,6.55,o.z);roof.rotation.y=Math.PI/4;scene.add(roof);box(2.2,2.7,.12,materials.door,o.x,1.35,o.z+o.d/2+.08);for(const dx of [-2.5,2.5])box(1.5,1.5,.12,materials.window,o.x+dx,3.3,o.z+o.d/2+.08)}else{box(.8,2.6,.8,materials.trunk,o.x,1.3,o.z);sphere(2.5,materials.leaves,o.x,4.2,o.z,scene);sphere(1.7,materials.leaves,o.x+1.1,4.7,o.z,scene)}}
function person(color){const g=new THREE.Group(),shirt=material(color);box(.8,.9,.5,shirt,0,1.15,0,g);sphere(.46,materials.skin,0,2,0,g);box(.85,.28,.72,materials.hair,0,2.3,0,g);for(const x of [-.2,.2]){box(.23,.7,.25,materials.pants,x,.35,0,g);sphere(.055,materials.black,x,2.04,.4,g)}for(const x of [-.53,.53])box(.2,.7,.23,shirt,x,1.1,0,g);const hat=new THREE.Mesh(new THREE.ConeGeometry(.58,1.05,8),materials.red);hat.position.y=3;g.add(hat);hat.visible=false;g.userData.hat=hat;scene.add(g);return g}
const keys=new Set(),pointers=new Map(),actors=new Map();let socket=null,playerId=null,state=null,roomName='',lastStatus='',lastSend=0,yaw=0,pitch=0,lastFrame=0,codeVisible=true,roleFlashTimer=null;
function randomCode(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',values=new Uint8Array(6);crypto.getRandomValues(values);return [...values].map(v=>chars[v%chars.length]).join('')}
function resetInputs(){keys.clear();pointers.clear();document.querySelectorAll('.pressed').forEach(e=>e.classList.remove('pressed'))}
function showOverlay(head,text,showRoom){overlay.hidden=false;stage.classList.add('intro');title.textContent=head;description.textContent=text;roomForm.hidden=!showRoom;lobby.hidden=showRoom;resetInputs()}
function send(m){if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify(m))}
function clearActors(){for(const a of actors.values())scene.remove(a);actors.clear()}
function connect(code){code=code.trim().toUpperCase();if(!/^[A-Z0-9]{4,8}$/.test(code)){connection.textContent='Enter a room code with 4–8 letters or numbers.';return}if(socket){socket.close();socket=null}clearActors();roomName=code;roomCode.value=code;playerId=null;state=null;lastStatus='';connection.textContent='Connecting to room '+code+'…';const protocol=location.protocol==='https:'?'wss:':'ws:',ws=new WebSocket(`${protocol}//${location.host}/api/hide/${code}`);socket=ws;
 ws.addEventListener('message',event=>{if(socket!==ws)return;try{const m=JSON.parse(event.data);if(m.type==='joined'){playerId=m.id;codeVisible=true;roomToggle.hidden=false;refreshCodeToggle();shareCode.textContent=code;roomForm.hidden=true;lobby.hidden=false;roomLabel.textContent='ROOM '+code;connection.textContent='Connected!'}else if(m.type==='notice')lobbyStatus.textContent=m.message;else if(m.type==='snapshot'){const previous=state?.status,previousRole=state?.players.find(p=>p.id===playerId)?.role;state=m;if(previous!=='playing'&&m.status==='playing'){yaw=0;pitch=0;for(const p of m.players){const actor=actors.get(p.id);if(actor)actor.position.set(p.x,0,p.z)}}else if(previous==='playing'&&m.status==='playing'){const newRole=m.players.find(p=>p.id===playerId)?.role;if(previousRole&&newRole&&previousRole!==newRole){roleFlash.textContent=newRole==='seeker'?'You are the seeker!':'Nice catch! You are a hider now!';roleFlash.hidden=false;clearTimeout(roleFlashTimer);roleFlashTimer=setTimeout(()=>{roleFlash.hidden=true},2500)}}refreshUI()}}catch{}});
 ws.addEventListener('error',()=>{if(socket===ws)connection.textContent='Could not connect. Please try again.'});ws.addEventListener('close',()=>{if(socket!==ws)return;socket=null;playerId=null;state=null;roomToggle.hidden=true;clearActors();roomLabel.textContent='Disconnected';showOverlay('Connection lost','Check your connection and create or rejoin a room.',true);connection.textContent='Your room code was '+roomName+'.'})}
function refreshCodeToggle(){shareCode.textContent=codeVisible?roomName:'••••••';roomToggle.textContent=codeVisible?'Hide':'Show';roomToggle.setAttribute('aria-label',codeVisible?'Hide room code':'Show room code');if(state)roomLabel.textContent=codeVisible?`ROOM ${roomName} · ${state.players.length}/30`:`ROOM HIDDEN · ${state.players.length}/30`}
roomToggle.addEventListener('click',()=>{codeVisible=!codeVisible;refreshCodeToggle()});
function refreshUI(){if(!state)return;const me=state.players.find(p=>p.id===playerId),count=state.players.length;roomLabel.textContent=codeVisible?`ROOM ${roomName} · ${count}/30`:`ROOM HIDDEN · ${count}/30`;playersLabel.textContent=`${count} / 30 players in this room`;remainingEl.textContent=String(me?.tags||0);const headStart=state.status==='playing'?state.headStart:0;const seconds=Math.ceil(state.status==='playing'?(headStart>0?headStart:state.remaining):300);timeCaption.textContent=headStart>0?'HEAD START':'HUNT TIME';timeEl.textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;
 if(me){roleEl.textContent=me.caught?'Caught!':me.role==='seeker'?'Seeker':me.role==='hider'?'Hider':me.role==='spectator'?'Spectator':'Waiting';hint.textContent=me.role==='seeker'?(headStart>0?'Wait while the hiders get a 30-second head start.':'Touch a hider to swap roles!'):me.role==='hider'?(headStart>0?'Run and hide! The seeker is waiting.':'Avoid the seeker. If touched, you become the seeker!'):me.role==='spectator'?'You joined mid-round. You can play next round.':'Share the room code with your friends.'}
 if(state.status!==lastStatus){lastStatus=state.status;if(state.status==='playing'){overlay.hidden=true;stage.classList.remove('intro');lobbyStatus.textContent='Share the room code with your friends. At least 2 players are needed.'}else if(state.status==='finished'){const myRole=state.players.find(p=>p.id===playerId)?.role;showOverlay(myRole==='hider'?'You win! 🎉':myRole==='seeker'?'Time is up!':'Round finished!',myRole==='hider'?'You were a hider when time ran out!':myRole==='seeker'?'You were the seeker when time ran out. Try again!':'The round is over. Join the next one!',false);startRound.textContent='Play again'}else if(state.status==='ended'){showOverlay('Round ended','A player left. Start another round when everyone is ready.',false);startRound.textContent='Play again'}}}
function has(name){return keys.has(name)||[...pointers.values()].includes(name)}
function moveInput(){if(!socket||socket.readyState!==WebSocket.OPEN)return;const forward=(has('up')?1:0)-(has('down')?1:0),side=(has('right')?1:0)-(has('left')?1:0),dx=-Math.sin(yaw)*forward+Math.cos(yaw)*side,dz=-Math.cos(yaw)*forward-Math.sin(yaw)*side;send({type:'move',dx,dz})}
function resize(){const w=stage.clientWidth,h=stage.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(stage);resize();
function frame(now){const dt=Math.min((now-lastFrame)/1000||0,.04);lastFrame=now;if(has('turnLeft'))yaw+=2*dt;if(has('turnRight'))yaw-=2*dt;if(has('lookUp'))pitch=Math.min(1.2,pitch+1.6*dt);if(has('lookDown'))pitch=Math.max(-1.2,pitch-1.6*dt);
 if(state){const present=new Set();for(const p of state.players){present.add(p.id);let actor=actors.get(p.id);if(!actor){actor=person(p.color);actor.position.set(p.x,0,p.z);actors.set(p.id,actor)}actor.visible=p.id!==playerId;actor.position.x+=(p.x-actor.position.x)*.3;actor.position.z+=(p.z-actor.position.z)*.3;actor.rotation.y=p.angle;actor.userData.hat.visible=p.role==='seeker';actor.scale.y=p.caught?.65:1}for(const [id,actor] of actors)if(!present.has(id)){scene.remove(actor);actors.delete(id)}const me=state.players.find(p=>p.id===playerId),actor=actors.get(playerId);if(me&&actor)camera.position.set(actor.position.x,1.72,actor.position.z);camera.rotation.set(pitch,yaw,0,'YXZ')}else{camera.position.set(0,12,18);camera.lookAt(0,0,0)}if(socket?.readyState===WebSocket.OPEN&&now-lastSend>80){lastSend=now;moveInput()}renderer.render(scene,camera);requestAnimationFrame(frame)}
const map={w:'up',arrowup:'up',s:'down',arrowdown:'down',a:'left',arrowleft:'left',d:'right',arrowright:'right',q:'turnLeft',e:'turnRight',r:'lookUp',f:'lookDown'};window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement)return;const key=map[e.key.toLowerCase()];if(key){e.preventDefault();keys.add(key)}});window.addEventListener('keyup',e=>{const key=map[e.key.toLowerCase()];if(key)keys.delete(key)});window.addEventListener('blur',resetInputs);document.addEventListener('visibilitychange',()=>{if(document.hidden)resetInputs()});
for(const button of document.querySelectorAll('[data-move],[data-look]')){const lookup={up:'lookUp',down:'lookDown',left:'turnLeft',right:'turnRight'},name=button.dataset.move||lookup[button.dataset.look];button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);pointers.set(e.pointerId,name);button.classList.add('pressed')});const release=e=>{pointers.delete(e.pointerId);if(![...pointers.values()].includes(name))button.classList.remove('pressed')};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release)}
let dragPoint=null;canvas.addEventListener('pointerdown',e=>{if(!state||state.status!=='playing')return;dragPoint={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!dragPoint)return;yaw-=(e.clientX-dragPoint.x)*.007;pitch=THREE.MathUtils.clamp(pitch-(e.clientY-dragPoint.y)*.007,-1.2,1.2);dragPoint={x:e.clientX,y:e.clientY}});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>{dragPoint=null});
document.querySelector('#create').addEventListener('click',()=>connect(randomCode()));document.querySelector('#join').addEventListener('click',()=>connect(roomCode.value));startRound.addEventListener('click',()=>send({type:'start'}));requestAnimationFrame(frame);
